const int BUTTON_PIN = 14; // ESP32 GPIO 14 (D14)
const int GREEN_LED = 15;  // ESP32 GPIO 15 (D15) - Normal
const int ORANGE_LED = 4;  // ESP32 GPIO 4 (D4)   - Alert

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP); // Internal pull-up to 3.3V
  pinMode(GREEN_LED, OUTPUT);
  pinMode(ORANGE_LED, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int state = digitalRead(BUTTON_PIN);
  if (state == LOW) { // Pressed down to Ground (0V)!
    digitalWrite(GREEN_LED, LOW);   // Normal OFF
    digitalWrite(ORANGE_LED, HIGH); // Alert ON
  } else {            // Released (3.3V pull-up active)
    digitalWrite(GREEN_LED, HIGH);  // Normal ON
    digitalWrite(ORANGE_LED, LOW);  // Alert OFF
  }
  delay(50); // 50ms contact debounce delay
}

