#include <WiFi.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// Replace with your local classroom Wi-Fi or hotspot
const char* WIFI_SSID = "YOUR_WIFI_NAME";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";

// ThingSpeak channel details (Unlocked via Puzzle!)
const char* CHANNEL_ID = "3594258";
const char* READ_API_KEY = "XKXDZN01ERL8CVHX";

#define OLED_SDA 21
#define OLED_SCL 22
#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define OLED_RESET -1

Adafruit_SSD1306 display(
  OLED_WIDTH,
  OLED_HEIGHT,
  &Wire,
  OLED_RESET
);

const unsigned long UPDATE_INTERVAL_MS = 20000;
unsigned long lastUpdateMs = 0;

void showMessage(const char* line1, const char* line2 = "") {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(0, 18);
  display.println(line1);
  display.println(line2);
  display.display();
}

void connectToWiFi() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD, 6);

  showMessage("Connecting to Wi-Fi...");

  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }

  Serial.println();
  Serial.println("Wi-Fi connected");
  Serial.print("IP address: ");
  Serial.println(WiFi.localIP());
}

void fetchLatestReadings() {
  if (WiFi.status() != WL_CONNECTED) {
    connectToWiFi();
  }

  String url = "http://api.thingspeak.com/channels/";
  url += CHANNEL_ID;
  url += "/feeds/last.json?api_key=";
  url += READ_API_KEY;

  HTTPClient http;
  http.begin(url);

  int responseCode = http.GET();
  String response = http.getString();

  Serial.printf("ThingSpeak HTTP code: %d\n", responseCode);
  Serial.println("ThingSpeak response:");
  Serial.println(response);

  http.end();

  if (responseCode != 200) {
    showMessage("ThingSpeak error", "Check Serial Monitor");
    return;
  }

  JsonDocument doc;
  DeserializationError error = deserializeJson(doc, response);

  if (error) {
    Serial.print("JSON error: ");
    Serial.println(error.c_str());
    showMessage("JSON read error", "Check Serial Monitor");
    return;
  }

  String tempText = doc["field1"].as<String>();
  String humidityText = doc["field2"].as<String>();

  if (tempText.length() == 0 || humidityText.length() == 0) {
    Serial.println("Missing field1 or field2 in response.");
    showMessage("Missing field data", "Check Serial Monitor");
    return;
  }

  float temperature = tempText.toFloat();
  float humidity = humidityText.toFloat();

  Serial.printf("Temperature: %.1f C\n", temperature);
  Serial.printf("Humidity: %.1f%%\n", humidity);

  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  display.setTextSize(1);
  display.setCursor(0, 5);
  display.println("ThingSpeak readings");

  display.setTextSize(2);
  display.setCursor(0, 25);
  display.printf("Temp: %.1f C", temperature);

  display.setCursor(0, 48);
  display.printf("Humi: %.1f%%", humidity);

  display.display();
}

void setup() {
  Serial.begin(115200);

  Wire.begin(OLED_SDA, OLED_SCL);

  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED not found. Check wiring and I2C address.");
    while (true) {
      delay(100);
    }
  }

  connectToWiFi();
  fetchLatestReadings();
  lastUpdateMs = millis();
}

void loop() {
  if (millis() - lastUpdateMs >= UPDATE_INTERVAL_MS) {
    lastUpdateMs = millis();
    fetchLatestReadings();
  }
}
